const fs = require('fs');
const n = Number(fs.readFileSync(0, 'utf8').trim());
const rows = [];

for (let i = 0; i < n; i++) {
  const row = [];
  for (let j = 0; j < n; j++) {
    row.push(Math.min(i + 1, j + 1, n - i, n - j));
  }
  rows.push(row.join(' '));
}

console.log(rows.join('\n'));
